<script setup lang="ts">
import ModuleHeading from '../writing/ModuleHeading.vue'
import { ref,onBeforeUnmount } from 'vue'
import PlaceForm from './PlaceForm.vue'
import { request } from '../api'
import { type Connections,type Asset,type Place,type RecordRef } from './archive'
import PrivatePreview from './PrivatePreview.vue'
const props=defineProps<{value:Connections;recordId?:string;disabled:boolean;workspacePanel?:boolean;recordsOnly?:boolean}>()
const emit=defineEmits<{(e:'pending',value:boolean):void}>()
const placeDraft=ref<Partial<Place>|null>(null),placeSaving=ref(false),placeMessage=ref('')
function beginPlace(place?:Place){if(placeSaving.value||props.disabled)return;placeDraft.value=place?JSON.parse(JSON.stringify(place)):{name:'',country:'',region:'',city:'',address:'',category:'',notes:'',latitude:null,longitude:null,active:true};emit('pending',true)}
function cancelPlace(){if(placeSaving.value)return;placeDraft.value=null;emit('pending',false)}
async function savePlace(){if(!placeDraft.value||placeSaving.value||props.disabled)return;placeSaving.value=true;error.value='';try{const d=placeDraft.value;const payload={...Object.fromEntries(['name','country','region','city','address','category','notes','active'].map(k=>[k,(d as any)[k]])),latitude:d.latitude===''?null:d.latitude,longitude:d.longitude===''?null:d.longitude};const result=await request('/admin/archive/places'+(d.id?'/'+d.id:''),{method:d.id?'PUT':'POST',body:JSON.stringify({...payload,...(d.id?{expected_revision:d.revision}:{})})});const i=props.value.places.findIndex(p=>p.id===result.id);if(i>=0)props.value.places[i]=result;else props.value.places.push(result);placeDraft.value=null;placeMessage.value='地点已保存至地点库，文章关联将随记录保存。';emit('pending',false)}catch(e){error.value=String(e)}finally{placeSaving.value=false}}
onBeforeUnmount(()=>emit('pending',false))
const picker=ref<''|'media'|'links'|'places'>(''),q=ref(''),items=ref<any[]>([]),page=ref(1),total=ref(0),loading=ref(false),error=ref('')
async function load(){if(loading.value||!picker.value)return;loading.value=true;error.value='';try{const url=picker.value==='links'?'/admin/content/records':'/admin/archive/'+picker.value;const result=await request(url+'?'+new URLSearchParams({q:q.value,page:String(page.value),page_size:'12'})) as {items:any[];total:number};items.value=result.items;total.value=result.total}catch(e){error.value=String(e)}finally{loading.value=false}}
function open(mode:'media'|'links'|'places'){if(loading.value)return;picker.value=picker.value===mode?'':mode;q.value='';page.value=1;items.value=[];void load()}
function search(){page.value=1;void load()}
function turn(delta:number){page.value+=delta;void load()}
function add(item:any){if(picker.value==='media')props.value.media.push({id:item.id,cover:!props.value.media.length,caption:'',asset:item as Asset});else if(picker.value==='places')props.value.places.push(item as Place);else props.value.links.push({id:item.id,title:item.title,type_id:item.type_id,deleted:false,label:'相关内容'})}
function chosen(id:string){return picker.value==='media'?props.value.media.some(x=>x.id===id):picker.value==='places'?props.value.places.some(x=>x.id===id):props.value.links.some(x=>x.id===id)||id===props.recordId}
function move(index:number,direction:number){const next=index+direction;if(next<0||next>=props.value.media.length)return;const item=props.value.media.splice(index,1)[0]!;props.value.media.splice(next,0,item)}
function cover(index:number){props.value.media.forEach((m,i)=>{m.cover=i===index})}
</script>
<template><section class="connections-editor"><ModuleHeading v-if="workspacePanel" kind="relations" title="关联内容" description="把相关的故事连接起来；解除关联不会删除原记录。"/><h3 v-else>{{recordsOnly?'关联记录':'历史图片与地点关联'}}</h3><p class="muted">选择已有资源；关联随“保存记录”一起提交，移除关联不会删除资源。</p>
<template v-if="!recordsOnly"><p v-if="placeMessage" class="muted" role="status">{{placeMessage}}</p><details v-if="placeDraft" open class="inline-place-editor"><summary>同页编辑地点</summary><fieldset :disabled="disabled||placeSaving"><PlaceForm :value="placeDraft"/><div class="actions"><button type="button" @click="savePlace">保存地点并关联</button><button type="button" class="quiet" @click="cancelPlace">取消地点编辑</button></div></fieldset></details><p v-if="error&&!picker" class="error" role="alert">{{error}}</p><div class="actions"><button type="button" class="quiet" :disabled="disabled||!!placeDraft" @click="beginPlace()">在此新建地点</button><button type="button" class="quiet" :disabled="disabled" @click="open('media')">选择媒体库图片</button><button type="button" class="quiet" :disabled="disabled" @click="open('places')">选择已有地点</button></div>
</template><button type="button" class="quiet" :disabled="disabled" @click="open('links')">选择关联记录</button><section v-if="picker" class="resource-picker"><h4>{{picker==='media'?'媒体库图片':picker==='links'?'关联记录':'地点选择'}}</h4><label>搜索可选资源<input v-model="q" type="search" maxlength="200" @keydown.enter.prevent="search" /></label><button type="button" :disabled="loading||disabled" @click="search">搜索可选资源</button><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="loading">正在搜索…</p>
<div class="picker-grid"><button v-for="item in items" :key="item.id" type="button" class="resource-item" :disabled="disabled||chosen(item.id)||item.active===false" @click="add(item)"><PrivatePreview v-if="picker==='media'" :id="item.id" :alt="item.alt" /><strong>{{item.title||item.name||item.filename}}</strong><small>{{chosen(item.id)?'已选择 / 当前记录':item.active===false?'已停用':'添加关联'}}</small></button></div><p v-if="!loading&&!items.length" class="muted">没有结果，可先到媒体库、内容记录或地点管理中创建。</p><div class="pagination"><button type="button" class="quiet" :disabled="loading||disabled||page<=1" @click="turn(-1)">上一页资源</button><span>{{page}} / {{Math.max(1,Math.ceil(total/12))}}</span><button type="button" class="quiet" :disabled="loading||disabled||page*12>=total" @click="turn(1)">下一页资源</button></div></section>
<template v-if="!recordsOnly"><h4>已选图片（{{value.media.length}}）</h4><div v-for="(m,i) in value.media" :key="m.id" class="selected-media"><PrivatePreview :id="m.id" :alt="m.asset.alt" /><div><strong>{{m.asset.title||m.asset.filename}}</strong><label>记录级图片说明<input v-model="m.caption" maxlength="2000" :disabled="disabled" /></label><div class="actions"><button type="button" class="quiet" :disabled="disabled||i===0" @click="move(i,-1)">图片上移</button><button type="button" class="quiet" :disabled="disabled||i===value.media.length-1" @click="move(i,1)">图片下移</button><button type="button" class="quiet" :disabled="disabled" @click="cover(i)">{{m.cover?'当前封面':'设为封面'}}</button><button type="button" class="quiet" :disabled="disabled" @click="value.media.splice(i,1)">解除图片关联</button></div></div></div>
</template><h4>关联记录（从当前记录指向）</h4><div v-for="(l,i) in value.links" :key="l.id+'-'+i" class="linked-item"><strong>{{l.title}}{{l.deleted?'（已删除，历史引用保留）':''}}</strong><label>关系名称<input v-model="l.label" required maxlength="80" :disabled="disabled||l.deleted" /></label><button type="button" class="quiet" :disabled="disabled" @click="value.links.splice(i,1)">解除记录关联</button></div><p class="muted">关系有方向；可互相关联或形成循环，不允许关联自身。同一目标与关系名称不能重复。</p>
<template v-if="!recordsOnly"><h4>已选地点</h4><div v-for="(p,i) in value.places" :key="p.id" class="linked-item"><strong>{{p.name}}{{p.active?'':'（停用，原引用保留）'}}</strong><p class="muted">{{p.city}} {{p.address}}</p><button type="button" class="quiet" :disabled="disabled||!!placeDraft" @click="beginPlace(p)">在此编辑地点</button><button type="button" class="quiet" :disabled="disabled" @click="value.places.splice(i,1)">解除地点关联</button></div>
</template></section></template>
